function fluidSize(width, minPx, maxPx, minWidth, maxWidth) {
  const line = minPx + ((maxPx - minPx) * (width - minWidth)) / (maxWidth - minWidth);
  return Math.max(minPx, Math.min(maxPx, line));
}

