function fluidParts(minPx, maxPx, minWidth, maxWidth) {
  const slopeVw = ((maxPx - minPx) * 100) / (maxWidth - minWidth);
  const interceptPx = minPx - (slopeVw * minWidth) / 100;
  return { slopeVw, interceptPx };
}

